import type { AppNotification } from '@/types/shared.generated';

/** "Kari", "Kari og Ola", "Kari og 3 andre". */
export function actorsLabel(notification: AppNotification) {
  const [first, second] = notification.actors;
  const name = first?.name ?? 'Noen';
  const others = notification.actorCount - 1;
  if (others <= 0) return name;
  if (others === 1 && second) return `${name} og ${second.name}`;
  return `${name} og ${others} ${others === 1 ? 'annen' : 'andre'}`;
}

function quoted(context: string) {
  return context ? ` «${context}»` : '';
}

/** The sentence after the actor names, and a small icon for the notification type. */
export function describeNotification(notification: AppNotification): { actors: string; action: string; icon: string } {
  const { type, subject, context, target } = notification;
  const emojis = (notification.emojis ?? []).join('');
  const actors = actorsLabel(notification);

  switch (type) {
    case 'mention':
      return {
        actors,
        action: target.commentId ? `nevnte deg i en kommentar på${quoted(context)}` : `nevnte deg i et innlegg:${quoted(context)}`,
        icon: '@',
      };
    case 'reply':
      return { actors, action: `svarte på kommentaren din på${quoted(context)}`, icon: '↩️' };
    case 'comment':
      return {
        actors,
        action: `kommenterte ${subject === 'event' ? 'arrangementet' : 'innlegget'} ditt${quoted(context)}`,
        icon: '💬',
      };
    case 'thread':
      return { actors, action: `kommenterte også på${quoted(context)}`, icon: '💬' };
    case 'reaction':
      return {
        actors,
        action: subject === 'comment'
          ? `reagerte ${emojis} på kommentaren din på${quoted(context)}`
          : `reagerte ${emojis} på ${subject === 'event' ? 'arrangementet' : 'innlegget'} ditt${quoted(context)}`,
        icon: notification.emojis?.[0] ?? '👍',
      };
    case 'event':
      return { actors, action: `la ut et nytt arrangement:${quoted(context)}`, icon: '📅' };
    default:
      return { actors, action: 'har ny aktivitet', icon: '🔔' };
  }
}
